}
static Statement *statement(Parser *p) {
    Token t=*peek(p);
    Statement *s;
    if(is(p,"{"))return block(p);
    if(accept(p,";"))return stmt(S_EMPTY,t);
    if(accept(p,"if")) {
        s=stmt(S_IF,t);
        s->a=paren_condition(p);
        newlines(p);
        s->body=statement(p);
        newlines(p);
        if(accept(p,"else")) {
            newlines(p);
            s->otherwise=statement(p);
        }
    }
    else if(accept(p,"while")) {
        s=stmt(S_WHILE,t);
        s->a=paren_condition(p);
        s->body=loop_body(p);
    }
    else if(accept(p,"do")) {
        s=stmt(S_DO,t);
        s->body=loop_body(p);
        newlines(p);
        expect(p,"while");
        s->a=paren_condition(p);
        terminator(p);
    }
    else if(accept(p,"for")) {
        expect(p,"(");
        ++p->depth;
        int at=p->at;
        if(at+3<p->tokens.count&&p->tokens.tokens[at].kind==T_NAME&&!strcmp(p->tokens.tokens[at+1].text,"in")&&p->tokens.tokens[at+2].kind==T_NAME&&!strcmp(p->tokens.tokens[at+3].text,")")) {
            s=stmt(S_FORIN,t);
            s->a=expr(E_VAR,name(p));
            expect(p,"in");
            s->second=name(p);
            expect(p,")");
        }
        else {
            s=stmt(S_FOR,t);
            if(!is(p,";"))s->a=expression(p);
            expect(p,";");
            newlines(p);
            if(!is(p,";"))s->b=expression(p);
            expect(p,";");
            newlines(p);
            if(!is(p,")"))s->c=expression(p);
            expect(p,")");
        }
        --p->depth;
        s->body=loop_body(p);
    }
    else {
        take(p);
        if(!strcmp(t.text,"print")||!strcmp(t.text,"printf")) {
            s=stmt(!strcmp(t.text,"print")?S_PRINT:S_PRINTF,t);
            int enclosed=0;
            if(is(p,"(")) {
                int nesting=0,end=p->at;
                for(;end<p->tokens.count;++end) {
                    if(!strcmp(p->tokens.tokens[end].text,"("))++nesting;
                    else if(!strcmp(p->tokens.tokens[end].text,")")&&!--nesting)break;
                }
                if(end+1<p->tokens.count) {
                    Token next=p->tokens.tokens[end+1];
                    enclosed=next.kind==T_NL||next.kind==T_EOF||!strcmp(next.text,";")||!strcmp(next.text,"}")||!strcmp(next.text,">")||!strcmp(next.text,">>");
                }
            }
            Expr list= {
                0
            };
            if(enclosed) {
                take(p);
                ++p->depth;
                expression_list(p,&list);
                expect(p,")");
                --p->depth;
            }
            else if(!end_simple(p)&&!is(p,">")&&!is(p,">>")) {
                p->output=1;
                expression_list(p,&list);
                p->output=0;
            }
            if(s->kind==S_PRINTF&&!list.count)fail(p,*peek(p));
            s->args=list.args;
            s->nargs=list.count;
            if(is(p,">")||is(p,">>")) {
                Token redir=take(p);
                s->append=!strcmp(redir.text,">>");
                s->redirect=concat(p);
                s->second=redir;
            }
        }
        else if(!strcmp(t.text,"delete")) {
            s=stmt(S_DELETE,t);
            s->a=atom(p);
            if(s->a->kind!=E_VAR&&s->a->kind!=E_ARRAY)fail(p,s->a->token);
        }
        else if(!strcmp(t.text,"next")) {
            s=stmt(S_NEXT,t);
            if(!p->in_function&&p->phase)fail(p,t);
        }
        else if(!strcmp(t.text,"break")||!strcmp(t.text,"continue")) {
            s=stmt(!strcmp(t.text,"break")?S_BREAK:S_CONTINUE,t);
            if(!p->loops)fail(p,t);
        }
        else if(!strcmp(t.text,"exit")||!strcmp(t.text,"return")) {
            s=stmt(!strcmp(t.text,"exit")?S_EXIT:S_RETURN,t);
            if(s->kind==S_RETURN&&!p->in_function)fail(p,t);
            if(!end_simple(p))s->a=expression(p);
        }
        else {
            --p->at;
            s=stmt(S_EXPR,t);
            s->a=expression(p);
        }
        terminator(p);
    }
    p->result.statement_lines[t.pos.line]=1;
    return s;
}
Syntax parse(Tokens tokens,int lines) {
    Parser *p=mem_new(sizeof *p);
    p->tokens=tokens;
    p->result.lines=lines;
    p->result.statement_lines=mem_new((size_t)lines+2);
    if(setjmp(p->failure))return p->result;
    while(peek(p)->kind!=T_EOF) {
        if(peek(p)->kind==T_NL||accept(p,";")) {
            if(peek(p)->kind==T_NL)take(p);
            continue;
        }
        Token t=*peek(p);
        if(accept(p,"function")) {
            Function *f=mem_new(sizeof *f);
            if(peek(p)->kind!=T_NAME&&peek(p)->kind!=T_FUNCTION)fail(p,*peek(p));
            f->token=take(p);
            expect(p,"(");
            if(!is(p,")")) {
                do {
                    newlines(p);
                    Token param=name(p);
                    f->params=mem_resize(f->params,(size_t)(f->np+1)*sizeof *f->params);
                    f->params[f->np++]=param;
                }
                while(accept(p,","));
            }
            expect(p,")");
            newlines(p);
            p->in_function=1;
            f->body=block(p);
            p->in_function=0;
            p->result.functions=mem_resize(p->result.functions,(size_t)(p->result.nf+1)*sizeof *p->result.functions);
            p->result.functions[p->result.nf++]=f;
        }
        else {
            Rule *r=mem_new(sizeof *r);
            r->token=t;
            if(accept(p,"BEGIN")) {
                r->kind=1;
                p->phase=1;
                r->action=block(p);
                p->phase=0;
            }
            else if(accept(p,"END")) {
                r->kind=2;
                p->phase=2;
                r->action=block(p);
                p->phase=0;
            }
            else if(is(p,"{")) {
                r->kind=0;
                r->action=block(p);
            }
            else {
                r->kind=3;
                r->start=expression(p);
                if(accept(p,",")) {
                    newlines(p);
                    r->end=expression(p);
                    r->kind=4;
                }
                if(is(p,"{"))r->action=block(p);
                else if(peek(p)->kind!=T_NL&&peek(p)->kind!=T_EOF&&!is(p,";"))fail(p,*peek(p));
            }
            p->result.rules=mem_resize(p->result.rules,(size_t)(p->result.nr+1)*sizeof *p->result.rules);
            p->result.rules[p->result.nr++]=r;
        }
    }
    return p->result;
}

#include "awk.h"
int valid_filename(const char *s) {
    if(!*s||*s=='.')return 0;
    for(;*s;++s)if(!isalnum((unsigned char)*s)&&*s!='.'&&*s!='_'&&*s!='-')return 0;
    return 1;
}
static int valid_name(const char *s) {
    if(!isalpha((unsigned char)*s)&&*s!='_')return 0;
    for(++s;*s;++s)if(!isalnum((unsigned char)*s)&&*s!='_')return 0;
    return 1;
}
Streams read_args(void) {
    Streams s= {
        .current=-1
    };
    FILE *f=fopen("input/args.txt","r");
    if(!f)exit(EXIT_FAILURE);
    char *line;
    while((line=read_line(f))) {
        Operand a= {
            0
        };
        char *text=line;
        if(!strncmp(text,"-F ",3)) {
            a.option=a.assignment=1;
            a.name=str_copy("FS");
            a.value=str_copy(text+3);
        }
        else {
            if(!strncmp(text,"-v ",3)) {
                a.option=1;
                text+=3;
            }
            char *equal=strchr(text,'=');
            if(equal) {
                *equal=0;
                if(a.option||valid_name(text)) {
                    a.assignment=1;
                    a.name=str_copy(text);
                    a.value=str_copy(equal+1);
                }
                else *equal='=';
            }
            if(!a.assignment)a.name=str_copy(text);
        }
        s.args=mem_resize(s.args,(size_t)(s.count+1)*sizeof *s.args);
        s.args[s.count++]=a;
        free(line);
    }
    fclose(f);
    return s;
}
char *getline_file(Streams *s,const char *name,int *status) {
    InputStream *in=NULL;
    for(int i=0;i<s->ni;++i)if(!strcmp(s->inputs[i]->name,name))in=s->inputs[i];
    if(!in) {
        in=mem_new(sizeof *in);
        in->name=str_copy(name);
        s->inputs=mem_resize(s->inputs,(size_t)(s->ni+1)*sizeof *s->inputs);
        s->inputs[s->ni++]=in;
    }
    if(!in->opened) {
        if(valid_filename(name)) {
            char *path=mem_new(strlen(name)+7);
            sprintf(path,"input/%s",name);
            in->file=fopen(path,"r");
            free(path);
        }
        if(!in->file) {
            *status=-1;
            return NULL;
        }
        in->opened=in->ever=1;
    }
    char *line=read_line(in->file);
    *status=line?1:0;
    if(line)++in->reads;
    return line;
}
int close_stream(Streams *s,const char *name) {
    int closed=0;
    for(int i=0;i<s->ni;++i)if(!strcmp(s->inputs[i]->name,name)&&s->inputs[i]->opened) {
        fclose(s->inputs[i]->file);
        s->inputs[i]->file=NULL;
        s->inputs[i]->opened=0;
        closed=1;
    }
    for(int i=0;i<s->no;++i)if(!strcmp(s->outputs[i]->name,name)&&s->outputs[i]->open) {
        s->outputs[i]->open=0;
        closed=1;
    }
    return closed?0:-1;
}
void output_string(Streams *s,const char *name,int append,const char *text) {
    if(!name) {
        buffer_text(&s->standard,text);
        ++s->writes;
        return;
    }
    OutputStream *out=NULL;
    for(int i=0;i<s->no;++i)if(!strcmp(s->outputs[i]->name,name))out=s->outputs[i];
    if(!out) {
        out=mem_new(sizeof *out);
        out->name=str_copy(name);
        s->outputs=mem_resize(s->outputs,(size_t)(s->no+1)*sizeof *s->outputs);
        s->outputs[s->no++]=out;
    }
    if(!out->open) {
        out->open=1;
        if(!append) {
            out->content.length=0;
            if(out->content.data)*out->content.data=0;
        }
    }
    buffer_text(&out->content,text);
    ++out->writes;
}
void write_streams(Streams *s) {
    FILE *f=fopen("output/stdout.txt","w");
    if(!f)exit(EXIT_FAILURE);
    if(s->standard.length)fwrite(s->standard.data,1,s->standard.length,f);
    fclose(f);
    for(int i=0;i<s->no;++i) {
        OutputStream *o=s->outputs[i];
        char *path=mem_new(strlen(o->name)+8);
        sprintf(path,"output/%s",o->name);
        f=fopen(path,"w");
        free(path);
        if(!f)exit(EXIT_FAILURE);
        if(o->content.length)fwrite(o->content.data,1,o->content.length,f);
        fclose(f);
    }
}

#include "awk.h"
static Text *text_new(const char *s) {
    Text *t=mem_new(sizeof *t+strlen(s)+1);
    t->refs=1;
    strcpy(t->data,s);
    return t;
}
Value number(long long n) {
    return (Value) {
        .kind=1,.number=n
    };
}
Value string(const char *s) {
    return (Value) {
        .kind=2,.text=text_new(s)
    };
}
Value value_copy(Value v) {
    if(v.text)++v.text->refs;
    return v;
}
void value_free(Value v) {
    if(v.text&&!--v.text->refs)free(v.text);
}
static int whitespace(int c) {
    return c==' '||c=='\t'||c=='\n';
}
static long long parse_number(const char *s) {
    while(whitespace(*s))++s;
    int sign=1;
    if(*s=='+'||*s=='-') {
        if(*s=='-')sign=-1;
        ++s;
    }
    long long n=0;
    while(isdigit((unsigned char)*s))n=n*10+*s++-'0';
    return sign*n;
}
Value input_value(const char *s) {
    Value v=string(s);
    const char *p=s;
    while(whitespace(*p))++p;
    if(*p=='+'||*p=='-')++p;
    const char *start=p;
    while(isdigit((unsigned char)*p))++p;
    int digits=p>start;
    while(whitespace(*p))++p;
    if(digits&&!*p) {
        v.kind=3;
        v.number=parse_number(s);
    }
    return v;
}
long long numeric(Value v) {
    return v.kind==0?0:v.kind==1||v.kind==3?v.number:parse_number(v.text->data);
}
char *textual(Value v) {
    if(v.kind==0)return str_copy("");
    if(v.text)return str_copy(v.text->data);
    char text[40];
    sprintf(text,"%lld",v.number);
    return str_copy(text);
}
int truth(Value v) {
    return v.kind==1||v.kind==3?v.number!=0:v.kind==2&&*v.text->data;
}
int compare(Value a,Value b) {
    if(a.kind!=2&&b.kind!=2) {
        long long x=numeric(a),y=numeric(b);
        return (x>y)-(x<y);
    }
    char *x=textual(a),*y=textual(b);
    int n=strcmp(x,y);
    free(x);
    free(y);
    return n;
}
void value_write(FILE *f,Value v) {
    if(!v.kind) {
        fputs("(uninitialized)",f);
        return;
    }
    if(v.kind==1) {
        fprintf(f,"%lld",v.number);
        return;
    }
    fputc('"',f);
    for(const unsigned char *s=(const unsigned char*)v.text->data;*s;++s) {
        if(*s=='"'||*s=='\\') {
            fputc('\\',f);
            fputc(*s,f);
        }
        else if(*s=='\n')fputs("\\n",f);
        else if(*s=='\t')fputs("\\t",f);
        else if(*s<32||*s>126)fprintf(f,"\\%03o",*s);
        else fputc(*s,f);
    }
    fputc('"',f);
    if(v.kind==3)fputs(" (strnum)",f);
}
static void piece(char ***items,int *count,const char *s,size_t n) {
    *items=mem_resize(*items,(size_t)(*count+1)*sizeof **items);
    char *p=mem_new(n+1);
    memcpy(p,s,n);
    (*items)[(*count)++]=p;
}
char **split_string(const char *s,const char *sep,int *count) {
    char **items=NULL;
    *count=0;
    if(!strcmp(sep," ")) {
        while(*s) {
            while(whitespace(*s))++s;
            const char *start=s;
            while(*s&&!whitespace(*s))++s;
            if(s>start)piece(&items,count,start,(size_t)(s-start));
        }
    }
    else if(!*sep) {
        for(;*s;++s)piece(&items,count,s,1);
    }
    else if(*s) {
        const char *start=s,*found;
        size_t length=strlen(sep);
        while((found=strstr(start,sep))) {
            piece(&items,count,start,(size_t)(found-start));
            start=found+length;
        }
        piece(&items,count,start,strlen(start));
    }
    return items;
}
static int integer_key(const char *s) {
    if(!strcmp(s,"0"))return 1;
    if(*s=='-')++s;
    if(*s<'1'||*s>'9')return 0;
    while(isdigit((unsigned char)*s))++s;
    return !*s;
}
int key_compare(const void *a,const void *b) {
    const char *x=*(const char*const*)a,*y=*(const char*const*)b;
    int ix=integer_key(x),iy=integer_key(y);
    if(ix!=iy)return ix?-1:1;
    if(ix) {
        long long nx=strtoll(x,NULL,10),ny=strtoll(y,NULL,10);
        return (nx>ny)-(nx<ny);
    }
    return strcmp(x,y);
}
void array_clear(Array *a) {
    for(int i=0;i<a->count;++i) {
        free(a->items[i]->key);
        value_free(a->items[i]->value);
        free(a->items[i]);
    }
    free(a->items);
    a->items=NULL;
    a->count=a->capacity=0;
}
Element *array_element(Array *a,const char *key,int create) {
    for(int i=0;i<a->count;++i)if(!strcmp(a->items[i]->key,key))return a->items[i];
    if(!create)return NULL;
    if(a->count==a->capacity) {
        a->capacity=a->capacity?2*a->capacity:8;
        a->items=mem_resize(a->items,(size_t)a->capacity*sizeof *a->items);
    }
    Element *e=mem_new(sizeof *e);
    e->key=str_copy(key);
    a->items[a->count++]=e;
    return e;
}
void array_delete(Array *a,const char *key) {
    for(int i=0;i<a->count;++i)if(!strcmp(a->items[i]->key,key)) {
        Element *e=a->items[i];
        free(e->key);
        value_free(e->value);
        free(e);
        memmove(a->items+i,a->items+i+1,(size_t)(a->count-i-1)*sizeof *a->items);
        --a->count;
        return;
    }
}
static char *special(Runtime *r,const char *name) {
    return textual(global_symbol(r,name)->global.value);
}
void set_record(Runtime *r,const char *s) {
    value_free(r->record);
    r->record=input_value(s);
    for(int i=0;i<r->nf;++i)value_free(r->fields[i]);
    free(r->fields);
    char *sep=special(r,"FS");
    int count;
    char **pieces=split_string(s,sep,&count);
    free(sep);
    r->fields=mem_new((size_t)count*sizeof *r->fields);
    r->nf=count;
    for(int i=0;i<count;++i) {
        r->fields[i]=input_value(pieces[i]);
        free(pieces[i]);
    }
    free(pieces);
}
void rebuild_record(Runtime *r) {
    char *sep=special(r,"OFS");
    Buffer b= {
        0
    };
    for(int i=0;i<r->nf;++i) {
        if(i)buffer_text(&b,sep);
        char *text=textual(r->fields[i]);
        buffer_text(&b,text);
        free(text);
    }
    value_free(r->record);
    r->record=input_value(b.data?b.data:"");
    free(b.data);
    free(sep);
}
void set_nf(Runtime *r,long long n,Position p) {
    if(n<0) {
        runtime_error(r,p,"negative NF");
        return;
    }
    for(int i=(int)n;i<r->nf;++i)value_free(r->fields[i]);
    r->fields=mem_resize(r->fields,(size_t)n*sizeof *r->fields);
    for(int i=r->nf;i<n;++i)r->fields[i]=string("");
    r->nf=(int)n;
    rebuild_record(r);
}
Value field_value(Runtime *r,long long index,Position p) {
    if(index<0) {
        runtime_error(r,p,"negative field index");
        return (Value) {
            0
        };
    }
    if(!index)return value_copy(r->record);
    return index<=r->nf?value_copy(r->fields[index-1]):(Value) {
        0
    };
}
void store_field(Runtime *r,long long index,Value v,Position p) {
    if(index<0) {
        runtime_error(r,p,"negative field index");
        return;
    }
    if(!index) {
        char *s=textual(v);
        set_record(r,s);
        free(s);
        return;
    }
    if(index>r->nf) {
        int old=r->nf;
        r->fields=mem_resize(r->fields,(size_t)index*sizeof *r->fields);
        for(int i=old;i<index;++i)r->fields[i]=string("");
        r->nf=(int)index;
    }
    value_free(r->fields[index-1]);
    r->fields[index-1]=value_copy(v);
    rebuild_record(r);
}
